  "Why it sounds like this:": { es: "Por qué suena así:", ar: "لماذا يُنطق هكذا:", zh: "为什么这样发音：", sw: "Kwa nini inasikika hivi:", sv: "Varför den låter så:", de: "Warum es so klingt:", pt: "Por que soa assim:", fr: "Pourquoi il se prononce ainsi :" },
  "✍️ Practise writing it": { es: "✍️ Practica escribirlo", ar: "✍️ تدرّب على كتابته", zh: "✍️ 练习书写", sw: "✍️ Fanya mazoezi ya kuiandika", sv: "✍️ Öva på att skriva den", de: "✍️ Schreiben üben", pt: "✍️ Praticar a escrita", fr: "✍️ S'entraîner à l'écrire" },
  "🤖 Explain more": { es: "🤖 Explicar más", ar: "🤖 اشرح أكثر", zh: "🤖 详细解释", sw: "🤖 Eleza zaidi", sv: "🤖 Förklara mer", de: "🤖 Mehr erklären", pt: "🤖 Explicar mais", fr: "🤖 En savoir plus" },
  "✍️ Writing practice": { es: "✍️ Práctica de escritura", ar: "✍️ تدريب الكتابة", zh: "✍️ 书写练习", sw: "✍️ Mazoezi ya kuandika", sv: "✍️ Skrivövning", de: "✍️ Schreibübung", pt: "✍️ Prática de escrita", fr: "✍️ Exercice d'écriture" },
  "Write the symbol in the square with your finger, pen or mouse.": { es: "Escribe el símbolo en el cuadro con el dedo, el lápiz o el ratón.", ar: "اكتب الرمز في المربع بإصبعك أو قلمك أو الفأرة.", zh: "用手指、笔或鼠标在方框中写出这个符号。", sw: "Andika alama ndani ya mraba kwa kidole, kalamu au kipanya.", sv: "Skriv symbolen i rutan med fingret, en penna eller musen.", de: "Schreib das Symbol mit Finger, Stift oder Maus in das Feld.", pt: "Escreva o símbolo no quadrado com o dedo, a caneta ou o mouse.", fr: "Écrivez le symbole dans la case avec le doigt, un stylet ou la souris." },
  "Trace": { es: "Calcar", ar: "تتبّع", zh: "描红", sw: "Fuatisha", sv: "Spåra", de: "Nachfahren", pt: "Traçar", fr: "Tracer" },
  "shows a faint guide,": { es: "muestra una guía tenue,", ar: "يُظهر دليلًا باهتًا،", zh: "会显示浅色描线，", sw: "inaonyesha mwongozo hafifu,", sv: "visar en svag förlaga,", de: "zeigt eine blasse Vorlage,", pt: "mostra um guia suave,", fr: "affiche un modèle pâle," },
  "shows it beside the pad, and": { es: "la muestra junto al panel, y", ar: "يُظهره بجانب اللوحة، و", zh: "会在书写板旁显示范例，而", sw: "inaionyesha kando ya kibao, na", sv: "visar den bredvid ytan, och", de: "zeigt es neben dem Feld, und", pt: "mostra ao lado da área, e", fr: "l'affiche à côté de la zone, et" },
  "From memory": { es: "De memoria", ar: "من الذاكرة", zh: "默写", sw: "Kwa kumbukumbu", sv: "Ur minnet", de: "Aus dem Gedächtnis", pt: "De memória", fr: "De mémoire" },
  "only plays the sound and shows the romanisation. Press": { es: "solo reproduce el sonido y muestra la romanización. Pulsa", ar: "يشغّل الصوت فقط ويعرض الكتابة اللاتينية. اضغط", zh: "只播放发音并显示罗马字。点击", sw: "inacheza sauti tu na kuonyesha herufi za Kilatini. Bonyeza", sv: "spelar bara ljudet och visar translitterationen. Tryck på", de: "spielt nur den Ton ab und zeigt die Umschrift. Drück", pt: "só toca o som e mostra a romanização. Aperte", fr: "joue seulement le son et affiche la romanisation. Appuyez sur" },
  "Check": { es: "Comprobar", ar: "تحقق", zh: "检查", sw: "Kagua", sv: "Kontrollera", de: "Prüfen", pt: "Verificar", fr: "Vérifier" },
  "to get a score.": { es: "para obtener una puntuación.", ar: "للحصول على درجة.", zh: "获得评分。", sw: "kupata alama.", sv: "för att få poäng.", de: "für eine Bewertung.", pt: "para receber uma nota.", fr: "pour obtenir un score." },
  "Drill: 10 random symbols": { es: "Ejercicio: 10 símbolos al azar", ar: "تمرين: 10 رموز عشوائية", zh: "练习：10 个随机符号", sw: "Zoezi: alama 10 za nasibu", sv: "Drill: 10 slumpade symboler", de: "Drill: 10 zufällige Symbole", pt: "Treino: 10 símbolos aleatórios", fr: "Entraînement : 10 symboles au hasard" },
